4	const TOAST_TIMEOUT = 4000;
5	
6	const toaster = new Toaster();
7	
8	function CornerButton() {
9	  const {add} = useToaster();
10	
11	  const showToast = useCallback(() => {
12	    add({
13	      // Уникальное имя — каждый клик добавляет новый тост, они складываются стопкой
14	      name: `corner-toast-${Date.now()}`,
15	      title: 'Уведомление',
16	      content: `Это всплывающее уведомление. Оно исчезнет само через ${TOAST_TIMEOUT / 1000} секунды.`,
17	      autoHiding: TOAST_TIMEOUT,
18	    });
19	  }, [add]);
20	
21	  return (
22	    <Button
23	      view="action"
24	      size="l"
25	      onClick={showToast}
26	      style={{position: 'fixed', right: 24, bottom: 24, zIndex: 1}}
27	    >
28	      Показать уведомление
29	    </Button>
30	  );
31	}
32	
33	export function App() {
34	  return (
35	    <ToasterProvider toaster={toaster}>
36	      <div style={{padding: 24}}>
37	        <Text variant="header-1">Всплывающие уведомления</Text>
38	        <Text variant="body-2" color="secondary" as="p">
39	          Нажмите кнопку в правом нижнем углу экрана — появится уведомление, которое само
40	          исчезнет через несколько секунд.
41	        </Text>
42	        <CornerButton />
43	      </div>
44	    </ToasterProvider>
45	  );
46	}
